def traiter_multi_ratios(self, ratios: list, n: int = 10) -> dict:
    """Exécute la reconstruction exacte pour chaque ratio via le modèle spectral individuel."""
    resultats = {}
    for ratio in ratios:
        resultats[ratio] = self.reconstruire_rapport_non_typique(ratio, n=n)
    return resultats
